<?php declare(strict_types=1);require __DIR__.'/../../includes/bootstrap.php';require_student();verify_csrf($_POST['csrf_token']??null);$uid=(int)current_user()['user_id'];$id=(int)$_POST['transaction_id'];db()->prepare('UPDATE transactions SET status="deleted",deleted_at=CURRENT_TIMESTAMP WHERE transaction_id=? AND user_id=? AND status="active"')->execute([$id,$uid]);add_activity($uid,'delete','transaction',$id);flash('success','Transaction moved to history.');redirect('student/transactions.php');